package com.bank.grpc;

import com.bank.grpc.gen.*;
import io.grpc.stub.StreamObserver;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class StatementServiceImpl extends StatementServiceGrpc.StatementServiceImplBase {
    private static final Logger log = Logger.getLogger(StatementServiceImpl.class.getName());

    @Override
    public void streamStatement(StatementRequest req, StreamObserver<TxnEntry> obs) {
        log.info(() -> "Streaming statement for " + req.getAccountId());
        BigDecimal balance = new BigDecimal("1000000"); // Rajesh SAV2001

        // Emit MANY responses on ONE call — the HTTP/2 streaming capability.
        List<String[]> txns = List.of(
            new String[]{"T1", "Salary credit", "75000"},
            new String[]{"T2", "Rent debit", "-25000"},
            new String[]{"T3", "Transfer to CUR3001", "-50000"});

        for (String[] t : txns) {
            BigDecimal amt = new BigDecimal(t[2]);
            balance = balance.add(amt);
            obs.onNext(TxnEntry.newBuilder()
                .setTxnId(t[0]).setDescription(t[1])
                .setAmount(t[2]).setRunningBalance(balance.toString())
                .build());
            log.info("Streamed " + t[0] + " bal=" + balance);
        }
        obs.onCompleted(); // final status sent via HTTP/2 TRAILERS
    }
}
