package com.bank.grpc;

import com.bank.grpc.gen.*;
import io.grpc.ManagedChannel;
import io.grpc.ManagedChannelBuilder;
import java.util.Iterator;
import java.util.logging.Logger;

public class StatementClient {
    private static final Logger log = Logger.getLogger(StatementClient.class.getName());
    public static void main(String[] args) {
        ManagedChannel channel = ManagedChannelBuilder
            .forAddress("localhost", 9090).usePlaintext().build();
        StatementServiceGrpc.StatementServiceBlockingStub stub =
            StatementServiceGrpc.newBlockingStub(channel);

        // Consume the server stream: many TxnEntry on one call.
        Iterator<TxnEntry> it = stub.streamStatement(
            StatementRequest.newBuilder().setAccountId("SAV2001").build());
        while (it.hasNext()) {
            TxnEntry e = it.next();
            log.info(() -> e.getTxnId() + " " + e.getDescription()
                + " Rs." + e.getAmount() + " bal=Rs." + e.getRunningBalance());
        }
        channel.shutdown();
    }
}
